RELAY_SECRET = "ai-forge-commercial-secret-2026"<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" aria-hidden="true" role="img" class="iconify iconify--logos" width="37.07" height="36" preserveAspectRatio="xMidYMid meet" viewBox="0 0 256 198"><path fill="#41B883" d="M204.8 0H256L128 220.8L0 0h97.92L128 51.2L157.44 0h47.36Z"></path><path fill="#41B883" d="m0 0l128 220.8L256 0h-51.2L128 132.48L50.56 0H0Z"></path><path fill="#35495E" d="M50.56 0L128 133.12L204.8 0h-47.36L128 51.2L97.92 0H50.56Z"></path></svg><script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import CountUp from './CountUp.vue';
type Token = { cls: 'kw' | 'comp' | 'attr' | 'punc' | 'num' | 'str'; text: string };
type Convo = {
  q: string;
  line1: Token[];
  line2: Token[];
  badgeText: string;
  highlightNum: number;
  highlightUnit: string;
  decimals?: number;
};
const AI_CONVOS: Convo[] = [
  {
    q: 'translate "system-level optimization" --to zh',
    line1: [
      { cls: 'kw', text: 'import ' },
      { cls: 'punc', text: '{ ' },
      { cls: 'comp', text: 'translate' },
      { cls: 'punc', text: ' } ' },
      { cls: 'kw', text: 'from ' },
      { cls: 'str', text: '"@ai-toolkit/core"' }
    ],
    line2: [
      { cls: 'kw', text: 'const ' },
      { cls: 'comp', text: 'res' },
      { cls: 'punc', text: ' = ' },
      { cls: 'kw', text: 'await ' },
      { cls: 'comp', text: 'translate' },
      { cls: 'punc', text: '({ ' },
      { cls: 'attr', text: 'target' },
      { cls: 'punc', text: ': ' },
      { cls: 'str', text: '"Chinese"' },
      { cls: 'punc', text: ' })' }
    ],
    badgeText: 'Hy-MT2 1.8B 热推演耗时:',
    highlightNum: 386.67,
    highlightUnit: 'ms (120+ Tokens/s)',
    decimals: 2
  },
  {
    q: 'translate cache query (SQLite WAL)',
    line1: [
      { cls: 'kw', text: 'import ' },
      { cls: 'punc', text: '{ ' },
      { cls: 'comp', text: 'cacheQuery' },
      { cls: 'punc', text: ' } ' },
      { cls: 'kw', text: 'from ' },
      { cls: 'str', text: '"@ai-toolkit/core"' }
    ],
    line2: [
      { cls: 'kw', text: 'const ' },
      { cls: 'comp', text: 'hit' },
      { cls: 'punc', text: ' = ' },
      { cls: 'kw', text: 'await ' },
      { cls: 'comp', text: 'cacheQuery' },
      { cls: 'punc', text: '({ ' },
      { cls: 'attr', text: 'hash' },
      { cls: 'punc', text: ': ' },
      { cls: 'str', text: '"0x9f2a"' },
      { cls: 'punc', text: ' })' }
    ],
    badgeText: 'SQLite WAL 缓存碰撞:',
    highlightNum: 1.39,
    highlightUnit: 'ms (提速 1080 倍)',
    decimals: 2
  },
  {
    q: 'upscale image to 8k (RealESRGAN x4)',
    line1: [
      { cls: 'kw', text: 'import ' },
      { cls: 'punc', text: '{ ' },
      { cls: 'comp', text: 'upscale8k' },
      { cls: 'punc', text: ' } ' },
      { cls: 'kw', text: 'from ' },
      { cls: 'str', text: '"@ai-toolkit/core"' }
    ],
    line2: [
      { cls: 'kw', text: 'const ' },
      { cls: 'comp', text: 'img' },
      { cls: 'punc', text: ' = ' },
      { cls: 'kw', text: 'await ' },
      { cls: 'comp', text: 'upscale8k' },
      { cls: 'punc', text: '({ ' },
      { cls: 'attr', text: 'scale' },
      { cls: 'punc', text: ': ' },
      { cls: 'num', text: '4' },
      { cls: 'punc', text: ' })' }
    ],
    badgeText: '纯 GPU 渲染吞吐:',
    highlightNum: 2.54,
    highlightUnit: 'MPixels/s (6008万像素)',
    decimals: 2
  }
];
const idx = ref(0);
const typed = ref('');
const phase = ref<'prompt' | 'thinking' | 'code'>('prompt');
const codeLines = ref(0);
let timers: ReturnType<typeof setTimeout>[] = [];
const conv = computed(() => AI_CONVOS[idx.value]);
function clearTimers() {
  timers.forEach(clearTimeout);
  timers = [];
}
function schedule(fn: () => void, ms: number) {
  const id = setTimeout(fn, ms);
  timers.push(id);
}
function runConvo(i: number) {
  const c = AI_CONVOS[i];
  typed.value = '';
  phase.value = 'prompt';
  codeLines.value = 0;
  let delay = 300;
  for (let k = 0; k <= c.q.length; k++) {
    const slice = c.q.slice(0, k);
    schedule(() => {
      typed.value = slice;
    }, delay);
    delay += 40;
  }
  schedule(() => {
    phase.value = 'thinking';
  }, delay);
  delay += 600;
  schedule(() => {
    phase.value = 'code';
    codeLines.value = 1;
  }, delay);
  delay += 250;
  schedule(() => {
    codeLines.value = 2;
  }, delay);
  delay += 2600;
  schedule(() => {
    idx.value = (idx.value + 1) % AI_CONVOS.length;
  }, delay);
}
onMounted(() => {
  runConvo(0);
});
onUnmounted(() => {
  clearTimers();
});
watch(idx, i => {
  if (i === 0) return;
  clearTimers();
  runConvo(i);
});
</script>
<template>
  <div class="ln-feat-aichat w-full h-56 p-4 rounded-2xl bg-slate-950/80 border border-slate-800/80 font-mono text-xs flex flex-col justify-between overflow-hidden shadow-inner">
