<script setup lang="ts">
import { ref, useTemplateRef } from 'vue';
interface Position {
  x: number;
  y: number;
}
interface SpotlightCardProps {
  className?: string;
  spotlightColor?: string;
}
const { className = '', spotlightColor = 'rgba(165, 243, 252, 0.12)' } = defineProps<SpotlightCardProps>();
const divRef = useTemplateRef<HTMLDivElement>('divRef');
const isFocused = ref<boolean>(false);
const position = ref<Position>({ x: 0, y: 0 });
const opacity = ref<number>(0);
const handleMouseMove = (e: MouseEvent) => {
  if (!divRef.value || isFocused.value) return;
  const rect = divRef.value.getBoundingClientRect();
  position.value = { x: e.clientX - rect.left, y: e.clientY - rect.top };
};
const handleFocus = () => {
  isFocused.value = true;
  opacity.value = 0.6;
};
const handleBlur = () => {
  isFocused.value = false;
  opacity.value = 0;
};
const handleMouseEnter = () => {
  opacity.value = 0.6;
};
const handleMouseLeave = () => {
  opacity.value = 0;
};
</script><script setup lang="ts">
